 private Map<String,Object> addCatalog(Map<String,Object> identity,List<Long> phones,long target,String request){
  var item=new LinkedHashMap<>(identity);item.put("phoneModelIds",phones);var command=values("supplierCode","XD-SUP","items",List.of(item),"selectionName","工程主动选中","requestId",request);
  if(target>0){command.put("targetSelectionId",target);command.put("targetVersion",selections.detail(target).get("version"));}
  var preview=tx.execute(s->catalog.additionPreview(command));assertEquals(true,preview.get("canAdd"),preview.toString());command.put("previewToken",preview.get("previewToken"));return tx.execute(s->catalog.addToSelection(command));
 }

 private Map<String,Object> legacySource(String row,Map<String,Object> fields){
  var changes=values("name","历史供方款","supplierCode","XD-SUP","phoneModelIds",List.of(12L,13L),"currency","");changes.putAll(fields);
  add(List.of(op(row,changes)));
  jdbc.update("update plm_partner_record set data=data-'purpose',supplier_code=null where record_id=?",id());
  jdbc.update("update plm_partner_selection_row set data=jsonb_set(data-'rawQuoteFields'-'currencySource','{currency}','\"\"'::jsonb) where record_id=? and row_id=?::uuid",id(),row);
  return values("sourceKind","selection","recordId",id(),"rowId",row,"rowVersion",baseline(row).get("rowVersion"),"recordVersion",head.get("version"));
 }
