 private Map<String,Object> catalogCommand(Map<String,Object> source,List<Long> phones,long target,Object qty,String request){var item=new LinkedHashMap<>(source);item.put("phoneModelIds",phones);if(qty!=null)item.put("sampleQty",qty);var command=values("supplierCode","XD-SUP","selectionName","QA直接选样","requestId",request,"items",List.of(item));if(target>0){command.put("targetSelectionId",target);command.put("targetVersion",selections.detail(target).get("version"));}return command;}
 private Map<String,Object> saveCatalog(Map<String,Object> command){var preview=catalog.additionPreview(command);assertEquals(true,preview.get("canAdd"),preview.toString());command.put("previewToken",preview.get("previewToken"));return tx.execute(t->catalog.addToSelection(command));}
 private Map<String,Object> directCatalog(Map<String,Object> source,String request){var command=catalogCommand(source,List.of(12L),0,2L,request);command.put("targetMode","supplier_directory");command.remove("selectionName");return command;}
