 private long additionalDirectory(String name,String supplier,String purpose,boolean catalogSource,boolean deleted){long record=tx.execute(t->store.create("selection",name));var data=values("name",name,"supplierCode",supplier,"catalogSource",catalogSource);if(purpose!=null)data.put("purpose",purpose);jdbc.update("update plm_partner_record set supplier_code=?,data=?::jsonb,deleted_flag=? where record_id=?",supplier,encode(store.json,data),deleted?1:0,record);return record;}
 private long activeDirectoryCount(){return jdbc.queryForObject("select count(*) from plm_partner_record where kind='selection' and data->>'purpose'='my_selection' and coalesce(data->>'catalogSource','false')<>'true' and deleted_flag=0",Long.class);}
 @Test void directSupplierPreviewDoesNotCreateAndFirstSaveLeavesHistoricalBearSourceUntouched(){var originalRows=new ArrayList<Map<String,Object>>();for(int i=0;i<19;i++)originalRows.add(op(UUID.randomUUID().toString(),values("name","QA熊大旧款"+i,"supplierCode","XD-SUP","phoneModelIds",List.of(12L),"modelText","Phone12")));add(originalRows);var styles=new PartnerCatalogStyles(store);for(var operation:originalRows){String rid=text(operation.get("rowId"));tx.executeWithoutResult(t->styles.ensure("selection",id(),baseline(rid),0,"QA已存在原款身份","QA-source-cp-"+rid));}String selectedRow=text(originalRows.get(0).get("rowId"));historicalInitialHeader();String history=persistedRecord(id());long sourceEvents=jdbc.queryForObject("select count(*) from plm_partner_event where record_id=?",Long.class,id());var source=values("sourceKind","selection","recordId",id(),"rowId",selectedRow,"rowVersion",baseline(selectedRow).get("rowVersion"),"recordVersion",head.get("version"));var command=directCatalog(source,"QA-direct-first");long records=count("plm_partner_record"),rows=count("plm_partner_selection_row"),events=count("plm_partner_event"),sequence=jdbc.queryForObject("select last_value from plm_partner_record_record_id_seq",Long.class);var preview=catalog.additionPreview(command);assertEquals(0L,number(preview.get("targetSelectionId")));assertEquals("熊大样品目录",preview.get("targetName"));assertEquals(records,count("plm_partner_record"));assertEquals(rows,count("plm_partner_selection_row"));assertEquals(events,count("plm_partner_event"));assertEquals(sequence,jdbc.queryForObject("select last_value from plm_partner_record_record_id_seq",Long.class));command.put("previewToken",preview.get("previewToken"));var saved=tx.execute(t->catalog.addToSelection(command));long target=number(map(saved.get("selection")).get("id"));assertNotEquals(id(),target);assertEquals(1L,activeDirectoryCount());assertEquals(history,persistedRecord(id()));assertEquals(sourceEvents,jdbc.queryForObject("select count(*) from plm_partner_event where record_id=?",Long.class,id()));assertEquals(19L,jdbc.queryForObject("select count(*) from plm_partner_selection_row where record_id=?",Long.class,id()));assertEquals(2L,number(maps(selections.pageRows(target,Map.of()).get("content")).get(0).get("sampleQty")));assertEquals(0L,jdbc.queryForObject("select count(*) from plm_partner_record where kind in ('product','sample')",Long.class));}
 @Test void directSupplierReusesItsOneDeclaredDirectoryAndDeduplicatesWithoutAccumulatingQuantity(){var source=quoteSource();var command=directCatalog(source,"QA-direct-existing");var preview=catalog.additionPreview(command);assertEquals(id(),number(preview.get("targetSelectionId")));assertEquals(head.get("name"),preview.get("targetName"));var saved=saveCatalog(command);assertEquals(id(),number(map(saved.get("selection")).get("id")));assertEquals(true,tx.execute(t->catalog.addToSelection(command)).get("replayed"));var again=saveCatalog(directCatalog(source,"QA-direct-repeated-choice"));assertEquals(0L,number(again.get("addedCount")));assertEquals(1L,activeDirectoryCount());assertEquals(1,maps(selections.pageRows(id(),Map.of()).get("content")).size());assertEquals(2L,number(maps(selections.pageRows(id(),Map.of()).get("content")).get(0).get("sampleQty")));}
