 @Test void concurrentFirstSavesCannotCreateTwoSupplierDirectories() throws Exception {historicalInitialHeader();var source=quoteSource();var a=directCatalog(source,"QA-concurrent-first-a");var b=directCatalog(source,"QA-concurrent-first-b");a.put("previewToken",catalog.additionPreview(a).get("previewToken"));b.put("previewToken",catalog.additionPreview(b).get("previewToken"));var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);var successes=new AtomicInteger();var errors=new ConcurrentLinkedQueue<String>();try{Callable<Void> first=()->{start.await();try{tx.execute(t->catalog.addToSelection(a));successes.incrementAndGet();}catch(RuntimeException expected){errors.add(expected.getMessage());}return null;};Callable<Void> second=()->{start.await();try{tx.execute(t->catalog.addToSelection(b));successes.incrementAndGet();}catch(RuntimeException expected){errors.add(expected.getMessage());}return null;};var f=pool.submit(first);var s=pool.submit(second);start.countDown();f.get(15,TimeUnit.SECONDS);s.get(15,TimeUnit.SECONDS);assertEquals(1,successes.get());assertEquals(1,errors.size());assertTrue(errors.peek().contains("重新预览"),errors.toString());assertEquals(1L,activeDirectoryCount());assertEquals(1L,jdbc.queryForObject("select count(*) from plm_partner_selection_row r join plm_partner_record p on p.record_id=r.record_id where p.data->>'purpose'='my_selection'",Long.class));}finally{pool.shutdownNow();}}
 @Test void concurrentIdenticalRequestsReplayBeforeResolvingTheNewlyCreatedSupplierDirectory() throws Exception {historicalInitialHeader();var command=directCatalog(quoteSource(),"QA-same-request-concurrent");command.put("previewToken",catalog.additionPreview(command).get("previewToken"));var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{Callable<Map<String,Object>> save=()->{start.await();return tx.execute(t->catalog.addToSelection(command));};var a=pool.submit(save);var b=pool.submit(save);start.countDown();var first=new LinkedHashMap<>(a.get(15,TimeUnit.SECONDS));var second=new LinkedHashMap<>(b.get(15,TimeUnit.SECONDS));assertNotEquals(first.remove("replayed"),second.remove("replayed"));assertEquals(signature(store.json,first),signature(store.json,second));assertEquals(1L,activeDirectoryCount());assertEquals(1L,jdbc.queryForObject("select count(*) from plm_partner_event where action='catalog_add'",Long.class));assertEquals(1L,jdbc.queryForObject("select count(*) from plm_partner_create_request where kind='catalog_add' and request_id='QA-same-request-concurrent'",Long.class));assertEquals(1L,jdbc.queryForObject("select count(*) from plm_partner_selection_row r join plm_partner_record p on p.record_id=r.record_id where p.data->>'purpose'='my_selection'",Long.class));}finally{pool.shutdownNow();}}
