  var renamed=baseline(rid);assertFalse(renamed.containsKey("sampleColors"));input=typedReceipt(renamed,"橙色");assertEquals(List.of("橙色"),maps(samples.receiptPreview(id(),input).get("rows")).get(0).get("sampleColors"));
