  long color=receiptColor();jdbc.update("update plm_partner_selection_row set data=(data-'sampleColors')||?::jsonb where row_id=?::uuid",signature(store.json,values("selectedPairs",List.of(values("phoneModelId",12L,"colorId",color,"colorSnapshot",values("name","原黑色"))))),rid);
  var paired=new PartnerCatalogStyles(store).receiptSnapshot(id(),rid,false);assertEquals("selected_pairs",paired.get("receiptColorMode"));assertEquals(List.of(),paired.get("sampleColors"));
