 private Map<String,Object> draftSelection(){var created=saveCatalog(catalogCommand(quoteSource(),List.of(12L,13L),0,2L,"QA-draft"));head=selections.detail(number(map(created.get("selection")).get("id")));return maps(selections.pageRows(id(),Map.of()).get("content")).get(0);}
 private long receiptColor(){var colors=tx.execute(t->ranges.saveColors("XD-SUP",values("requestId","QA-receipt-color","reason","QA实际供应商原色","items",List.of(values("name","原黑色")))));return number(maps(colors.get("content")).get(0).get("id"));}
 private Map<String,Object> draftReceipt(Map<String,Object> row,long color){var input=values("version",head.get("version"),"requestId","QA-one-step-receipt","date","2026-10-22","location","QA公司柜","ownerName","QA国内工程","rows",List.of(values("clientRowId","actual-one","rowId",row.get("rowId"),"rowVersion",row.get("rowVersion"),"phoneModelId",12L,"colorId",color,"qty",2L)));bindReceiptScope(input);return input;}

 private void bindReceiptScope(Map<String,Object> input){long selection=number(input.getOrDefault("selectionId",id()));var reports=maps(samples.receiptPreview(selection,input).get("rows"));for(var row:maps(input.get("rows")))reports.stream().filter(report->text(report.get("clientRowId")).equals(text(row.get("clientRowId")))).findFirst().ifPresent(report->{if(!text(report.get("sourceScopeToken")).isEmpty())row.put("sourceScopeToken",report.get("sourceScopeToken"));});}
 private Map<String,Object> transition(String action,List<Map<String,Object>> targets){return values("version",head.get("version"),"requestId",UUID.randomUUID().toString(),"action",action,"rows",targets.stream().map(r->values("rowId",r.get("rowId"),"rowVersion",r.get("rowVersion"))).toList());}
