 private void raceReceiptAndCancel(boolean legacy) throws Exception {var row=draftSelection();long color=receiptColor();if(legacy){String rid=text(row.get("rowId"));head=tx.execute(t->selections.confirm(id(),confirmCommand(List.of(rid))));row=baseline(rid);}var receipt=draftReceipt(row,color);var cancel=transition("cancel",List.of(row));var single=values("sourceType","catalog","selectionId",id(),"selectionRowId",row.get("rowId"),"phoneModelId",12L,"colorId",color,"qty",2L,"date","2026-10-22","location","QA公司柜","person","QA工程","requestId","QA-legacy-race");var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);var successes=new AtomicInteger();try{Callable<Void> receive=()->{start.await();try{tx.execute(t->legacy?samples.create(single):samples.receiveSelection(id(),receipt));successes.incrementAndGet();}catch(RuntimeException expected){}return null;};Callable<Void> cancelTask=()->{start.await();try{tx.execute(t->selections.transitionRows(id(),cancel));successes.incrementAndGet();}catch(RuntimeException expected){}return null;};var first=pool.submit(receive);var second=pool.submit(cancelTask);start.countDown();first.get(15,TimeUnit.SECONDS);second.get(15,TimeUnit.SECONDS);assertEquals(1,successes.get());long actual=jdbc.queryForObject("select count(*) from plm_partner_record where kind='sample'",Long.class);assertEquals(actual==0,Boolean.TRUE.equals(baseline(text(row.get("rowId"))).get("discarded")));}finally{pool.shutdownNow();}}
