 @Test void legacySingleReceiptAndCancellationUseTheSameHeaderAndRowLocks() throws Exception {raceReceiptAndCancel(true);}

 private Map<String,Object> modelSheetSource() {
  String row=UUID.randomUUID().toString(),sibling=UUID.randomUUID().toString();
  add(List.of(op(row,values("name","型号表目标款","supplierCode","XD-SUP","unitPrice","19.00","currency","CNY","notes","原报价备注","phoneModelIds",List.of(12L))),op(sibling,values("name","另一款不能套用","supplierCode","XD-SUP","phoneModelIds",List.of(13L)))));
  jdbc.update("update plm_partner_record set data=data||'{\"catalogSource\":true,\"purpose\":\"catalog_source\"}'::jsonb where record_id=?",id());
  jdbc.update("insert into plm_attachment(attachment_id,file_name,version_no,content_type,file_size) values(77,'型号表原图.png','V1','image/png',605780)");
  jdbc.update("insert into plm_partner_file(record_id,attachment_id,purpose) values(?,77,'photo')",id());
  var command=values("sourceKind","selection","supplierCode","XD-SUP","recordId",id(),"rowId",row,"rowVersion",1L,"recordVersion",head.get("version"),"requestId","model-sheet-first","modelSheetRefs",List.of(Map.of("id",77L)),"entries",List.of(values("supplierIndex",1L,"rawBrandGroup","Apple","rawModelText","Phone 12","rawStatus","现货","rawNote","大孔"),values("supplierIndex",2L,"rawBrandGroup","Apple","rawModelText","Phone 13","rawStatus","开模中","rawNote","20号试模"),values("supplierIndex",3L,"rawBrandGroup","Apple","rawModelText","缺档型号","rawStatus","22号试模","rawNote","")));
  command.put("_sibling",sibling);return command;
 }
 private Map<String,Object> previewModelSheet(Map<String,Object> command) {
  var clean=new LinkedHashMap<>(command);clean.remove("_sibling");var preview=tx.execute(t->catalog.modelSheetPreview(clean));assertEquals(true,preview.get("canSave"));clean.put("previewToken",preview.get("previewToken"));return clean;
 }
 @Test void modelSheetPreviewIsReadOnlyAndSaveChangesOnlyOneStyleWithAllOriginalStates() {
  var source=modelSheetSource();String row=text(source.get("rowId")),sibling=text(source.remove("_sibling"));
  String before=persistedRow(row),other=persistedRow(sibling),header=persistedRecord(id());long events=count("plm_partner_event");
  tx.setReadOnly(true);var command=previewModelSheet(source);tx.setReadOnly(false);
  assertEquals(before,persistedRow(row));assertEquals(other,persistedRow(sibling));assertEquals(header,persistedRecord(id()));assertEquals(events,count("plm_partner_event"));
  var saved=tx.execute(t->catalog.saveModelSheet(command));assertEquals(false,saved.get("replayed"));assertEquals(true,saved.get("changed"));
  var raw=decode(store.json,jdbc.queryForObject("select data::text from plm_partner_selection_row where row_id=?::uuid",String.class,row));
  assertEquals("19.00",raw.get("unitPrice"));assertEquals("原报价备注",raw.get("notes"));assertEquals(List.of(12L,13L),PartnerSelectionService.scopeIds(raw.get("phoneModelIds")));
  var entries=maps(raw.get("supplierModelEntries"));assertEquals(3,entries.size());assertEquals("现货",entries.get(0).get("rawStatus"));assertEquals("开模中",entries.get(1).get("rawStatus"));assertEquals("20号试模",entries.get(1).get("rawNote"));assertEquals("22号试模",entries.get(2).get("rawStatus"));assertEquals(List.of(),entries.get(2).get("phoneModelIds"));
  assertEquals(other,persistedRow(sibling));assertEquals(2L,jdbc.queryForObject("select row_version from plm_partner_selection_row where row_id=?::uuid",Long.class,row));
  assertEquals(0,count("plm_partner_catalog_style"));assertEquals(0,count("plm_partner_spec"));assertEquals(0L,jdbc.queryForObject("select count(*) from plm_partner_record where kind in ('product','sample')",Long.class));
  var event=decode(store.json,jdbc.queryForObject("select data::text from plm_partner_event where record_id=? and action='catalog_model_sheet'",String.class,id()));
  assertEquals("19.00",map(event.get("before")).get("unitPrice"));assertEquals(3,maps(map(event.get("after")).get("supplierModelEntries")).size());
  assertEquals(true,map(saved.get("style")).get("canMaintainModelSheet"));assertEquals(1,maps(map(saved.get("style")).get("modelSheetFileDetails")).size());
  long revisions=count("plm_partner_selection_row_revision");assertEquals(true,tx.execute(t->catalog.saveModelSheet(command)).get("replayed"));assertEquals(revisions,count("plm_partner_selection_row_revision"));
  command.put("entries",List.of(values("supplierIndex",1L,"rawModelText","Phone 13","rawStatus","现货")));assertThrows(RuntimeException.class,()->tx.execute(t->catalog.saveModelSheet(command)));
 }
