 private Map<String,Object> typedReceipt(Map<String,Object> row,String color){
  var input=draftReceipt(row,0);input.put("requestId",UUID.randomUUID().toString());var actual=maps(input.get("rows")).get(0);actual.remove("colorId");actual.put("colorName",color);return input;
 }
 private SampleIdentityRegistry enableReceiptIdentities(){
  jdbc.execute("create table plm_product(product_id bigint primary key,deleted_flag int default 0);alter table plm_partner_record add column sample_identity_id bigint;create table plm_sample_identity(identity_id bigint primary key references plm_partner_record(record_id),identity_key text not null unique,source_type text,basis jsonb,created_at timestamp default now());create table plm_code_item(code_item_id bigserial primary key,code_type text,code_value text);insert into plm_code_item(code_type,code_value) values('color','03');");
  var identities=new SampleIdentityRegistry(store);ReflectionTestUtils.setField(samples,"identities",identities);return identities;
 }
