 @Test void spaceSeparatedSourceColoursSaveAsSeparateTwoPieceSamples(){
  String original="黑色 蓝色 灰蓝 墨绿 紫色 棕色";var names=List.of("黑色","蓝色","灰蓝","墨绿","紫色","棕色");
  var source=quoteSource();long quoteId=number(source.get("recordId"));
  tx.execute(t->new PartnerQuoteLines(store,permissions,selections).patch(quoteId,values("version",source.get("recordVersion"),"requestId","QA-source-colour-list","operations",List.of(values("rowId",source.get("rowId"),"rowVersion",source.get("rowVersion"),"changes",values("color",original))))));
  source.put("rowVersion",2L);source.put("recordVersion",store.load(quoteId,"supplier_quote",false).get("version"));
  var created=saveCatalog(catalogCommand(source,List.of(12L),0,2L,"QA-list-selection"));head=selections.detail(number(map(created.get("selection")).get("id")));
  var row=maps(selections.pageRows(id(),Map.of()).get("content")).get(0);var identities=enableReceiptIdentities();
  var invalid=typedReceipt(row,original);assertEquals(false,samples.receiptPreview(id(),invalid).get("canSave"));
  assertThrows(RuntimeException.class,()->tx.execute(t->samples.receiveSelection(id(),invalid)));
  assertEquals(0L,count("plm_supplier_color"));assertEquals(0L,count("plm_sample_identity"));
  var input=typedReceipt(row,"黑色");input.put("rows",names.stream().map(name->values("clientRowId","colour-"+name,"rowId",row.get("rowId"),"rowVersion",row.get("rowVersion"),"phoneModelId",12L,"colorName",name,"qty",2L)).toList());
  var preview=samples.receiptPreview(id(),input);assertEquals(true,preview.get("canSave"),preview.toString());
  assertEquals(names,maps(preview.get("rows")).get(0).get("sourceColors"));
  var saved=tx.execute(t->samples.receiveSelection(id(),input));var batches=maps(saved.get("batches"));
  assertEquals(names,batches.stream().map(batch->text(batch.get("colorName"))).toList());assertEquals(6,batches.size());
  assertEquals(6L,batches.stream().map(batch->number(batch.get("sampleIdentityId"))).distinct().count());
  long onhand=0;
  for(var batch:batches){assertEquals(2L,number(batch.get("qty")));long qty=number(map(identities.detail(number(batch.get("sampleIdentityId"))).get("balances")).get("onhand"));assertEquals(2L,qty);onhand+=qty;}
  assertEquals(12L,onhand);assertEquals(6L,count("plm_supplier_color"));assertEquals(6L,count("plm_sample_identity"));
  var projected=maps(selections.pageRows(id(),Map.of()).get("content")).get(0);var actualBatches=maps(projected.get("sampleBatches"));assertEquals(6,actualBatches.size());assertEquals(new HashSet<>(names),new HashSet<>(actualBatches.stream().map(batch->text(batch.get("colorName"))).toList()));assertTrue(actualBatches.stream().allMatch(batch->number(batch.get("qty"))==2L));
  assertEquals(signature(store.json,saved),signature(store.json,tx.execute(t->samples.receiveSelection(id(),input))));
  assertEquals(6L,jdbc.queryForObject("select count(*) from plm_partner_record where kind='sample'",Long.class));
 }
