 private Map<String,Object> concurrencySource(String kind){
  if(kind.equals("quote"))return quoteSource();String row=UUID.randomUUID().toString();add(List.of(op(row,values("name","并发源款","supplierCode","XD-SUP","phoneModelIds",List.of(12L,13L),"modelText","Phone12 / Phone13"))));jdbc.update("update plm_partner_record set data=data||'{\"catalogSource\":true,\"purpose\":\"catalog_source\"}'::jsonb where record_id=?",id());return values("sourceKind","selection","recordId",id(),"rowId",row,"rowVersion",baseline(row).get("rowVersion"),"recordVersion",head.get("version"));
 }
 private void sourceExclusiveLock(Map<String,Object> source,boolean rowOnly){
  if(!rowOnly)store.load(number(source.get("recordId")),text(source.get("sourceKind")).equals("quote")?"supplier_quote":"selection",true);
  String table=text(source.get("sourceKind")).equals("quote")?"plm_partner_quote_line":"plm_partner_selection_row",key=text(source.get("sourceKind")).equals("quote")?"line_id":"row_id";jdbc.queryForList("select "+key+" from "+table+" where record_id=? and "+key+"=?::uuid for update",source.get("recordId"),source.get("rowId"));
 }
 private void awaitLatch(CountDownLatch latch){try{assertTrue(latch.await(10,TimeUnit.SECONDS),"timed out waiting for real transaction choreography");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}}
 private boolean sqlState(Throwable error,String state){for(Throwable c=error;c!=null;c=c.getCause())if(c instanceof java.sql.SQLException sql&&state.equals(sql.getSQLState()))return true;return false;}
 private Map<String,Long> receiptWriteCounts(){var out=new LinkedHashMap<String,Long>();for(String table:List.of("plm_partner_record","plm_partner_event","plm_partner_revision","plm_partner_create_request","plm_partner_selection_row_revision"))out.put(table,count(table));return out;}
 @ParameterizedTest @CsvSource({"quote","selection"})
 void sourceConcurrencyReceiptFirstSerializesTheRealSourceWriterUntilReceiptCommit(String kind)throws Exception{
  var source=concurrencySource(kind);var row=liveSelected(source);var input=draftReceipt(row,receiptColor());var accepted=new CountDownLatch(1);var release=new CountDownLatch(1);var writerDone=new CountDownLatch(1);var writerStarted=new CountDownLatch(1);var readerPid=new AtomicInteger();var writerPid=new AtomicInteger();var pool=Executors.newFixedThreadPool(2);
  try{var reader=pool.submit(()->{try(var hook=mockStatic(PartnerCatalogScopes.class,CALLS_REAL_METHODS)){var first=new AtomicInteger();hook.when(()->PartnerCatalogScopes.requireToken(anyMap(),anyMap())).thenAnswer(call->{call.callRealMethod();if(first.getAndIncrement()==0){readerPid.set(jdbc.queryForObject("select pg_backend_pid()",Integer.class));assertEquals("read committed",jdbc.queryForObject("show transaction_isolation",String.class));accepted.countDown();awaitLatch(release);}return null;});return tx.execute(t->samples.receiveSelection(id(),input));}});awaitLatch(accepted);
   var writer=pool.submit(()->{tx.executeWithoutResult(t->{writerPid.set(jdbc.queryForObject("select pg_backend_pid()",Integer.class));writerStarted.countDown();changeSupply(source,values("phoneModelIds",List.of(13L),"modelText","Phone13"));});writerDone.countDown();return null;});awaitLatch(writerStarted);boolean committedBeforeReceipt=writerDone.await(1,TimeUnit.SECONDS);var writerWait=jdbc.queryForMap("select wait_event_type,wait_event from pg_stat_activity where pid=?",writerPid.get());if(!committedBeforeReceipt)assertEquals("Lock",writerWait.get("wait_event_type"));System.out.println("SOURCE_LOCK_PG_WAIT kind="+kind+" writer="+writerWait);release.countDown();var received=reader.get(15,TimeUnit.SECONDS);writer.get(15,TimeUnit.SECONDS);System.out.println("SOURCE_LOCK_EVIDENCE reader-first kind="+kind+" readerPid="+readerPid+" writerPid="+writerPid+" isolation=read_committed writerCommittedBeforeReceipt="+committedBeforeReceipt);assertNotEquals(readerPid.get(),writerPid.get());assertFalse(committedBeforeReceipt,"source committed a changed model range after token acceptance and before receipt commit");assertEquals(12L,number(maps(received.get("batches")).get(0).get("phoneModelId")));assertEquals(List.of(13L),scopeIds(liveScope(row).get("phoneModelIds")));
  }finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(20,TimeUnit.SECONDS));}
 }
 @ParameterizedTest @CsvSource({"quote,false","selection,false","quote,true","selection,true"})
 void sourceConcurrencyWriterFirstRejectsTheWholeReceiptAndRollsBackBeforeRetry(String kind,boolean rowOnly)throws Exception{
  var source=concurrencySource(kind);var row=liveSelected(source);var input=draftReceipt(row,receiptColor());var before=receiptWriteCounts();String original=persistedRow(text(row.get("rowId")));var locked=new CountDownLatch(1);var release=new CountDownLatch(1);var pool=Executors.newSingleThreadExecutor();
  try{var writer=pool.submit(()->{tx.executeWithoutResult(t->{sourceExclusiveLock(source,rowOnly);locked.countDown();awaitLatch(release);changeSupply(source,values("phoneModelIds",List.of(13L),"modelText","Phone13"));});return null;});awaitLatch(locked);RuntimeException failure=assertThrows(RuntimeException.class,()->tx.execute(t->samples.receiveSelection(id(),input)));assertTrue(sqlState(failure,"55P03"),failure.toString());assertFalse(sqlState(failure,"40P01"));assertEquals(before,receiptWriteCounts());assertEquals(original,persistedRow(text(row.get("rowId"))));assertEquals(0L,jdbc.queryForObject("select count(*) from plm_partner_record where kind='sample'",Long.class));assertEquals(1,jdbc.queryForObject("select 1",Integer.class));System.out.println("SOURCE_LOCK_EVIDENCE writer-first kind="+kind+" rowOnly="+rowOnly+" state=55P03 rollbackVerified=true");release.countDown();writer.get(15,TimeUnit.SECONDS);
  }finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(20,TimeUnit.SECONDS));}
 }
 @ParameterizedTest @CsvSource({"quote","selection"})
 void sourceConcurrencyReverseDraftRefreshDoesNotDeadlockOrPartiallyReceive(String kind)throws Exception{
  var source=concurrencySource(kind);var row=liveSelected(source);var input=draftReceipt(row,receiptColor());var before=receiptWriteCounts();var readerAtSource=new CountDownLatch(1);var writerAtRefresh=new CountDownLatch(1);var releaseReader=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);var styles=spy(new PartnerCatalogStyles(store));ReflectionTestUtils.setField(samples,"catalogStyles",styles);
  doAnswer(call->{readerAtSource.countDown();awaitLatch(releaseReader);return call.callRealMethod();}).when(styles).receiptSnapshot(anyLong(),anyString(),eq(true),any());var writerSelections=spy(selections);ReflectionTestUtils.setField(catalog,"selections",writerSelections);doAnswer(call->{writerAtRefresh.countDown();return call.callRealMethod();}).when(writerSelections).refreshCatalogDrafts(anyString(),anyLong(),anyString(),anyMap(),anySet(),anyString());
  try{var reader=pool.submit(()->{try{tx.execute(t->samples.receiveSelection(id(),input));return (RuntimeException)null;}catch(RuntimeException e){return e;}});awaitLatch(readerAtSource);var writer=pool.submit(()->{changeSupply(source,values("name","并发维护后款名","phoneModelIds",List.of(13L),"modelText","Phone13"));return null;});awaitLatch(writerAtRefresh);releaseReader.countDown();var failure=reader.get(15,TimeUnit.SECONDS);writer.get(15,TimeUnit.SECONDS);assertNotNull(failure,"receipt must back out when the source writer owns source locks and awaits draft refresh");assertTrue(sqlState(failure,"55P03"),failure.toString());assertFalse(sqlState(failure,"40P01"));assertEquals(0L,jdbc.queryForObject("select count(*) from plm_partner_record where kind='sample'",Long.class));assertEquals(before.get("plm_partner_create_request"),count("plm_partner_create_request"));assertEquals(false,baseline(text(row.get("rowId"))).get("confirmed"));assertEquals("并发维护后款名",baseline(text(row.get("rowId"))).get("name"));System.out.println("SOURCE_LOCK_EVIDENCE reverse-refresh kind="+kind+" state=55P03 writerCommitted=true noDeadlock=true");
  }finally{releaseReader.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(20,TimeUnit.SECONDS));}
 }

 private void withExclusiveSource(Map<String,Object> source,Runnable action)throws Exception{
  var locked=new CountDownLatch(1);var release=new CountDownLatch(1);var pool=Executors.newSingleThreadExecutor();try{var writer=pool.submit(()->{tx.executeWithoutResult(t->{sourceExclusiveLock(source,false);locked.countDown();awaitLatch(release);});return null;});awaitLatch(locked);action.run();release.countDown();writer.get(15,TimeUnit.SECONDS);}finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(20,TimeUnit.SECONDS));}
 }
 @ParameterizedTest @CsvSource({"quote","selection"})
 void sourceConcurrencyConfirmedSingleUsesSourceLockAndSuccessfulReplaysPrecedeAnyScopeLock(String kind)throws Exception{
  var source=concurrencySource(kind);var row=liveSelected(source);long color=receiptColor();var firstInput=draftReceipt(row,color);var first=tx.execute(t->samples.receiveSelection(id(),firstInput));head=selections.detail(id());var single=values("sourceType","catalog","selectionId",id(),"selectionRowId",row.get("rowId"),"phoneModelId",13L,"colorId",color,"qty",2L,"date","2026-10-22","location","QA公司柜","person","QA国内工程","sourceScopeToken",liveScope(row).get("sourceScopeToken"),"requestId","QA-single-concurrent");var before=receiptWriteCounts();String frozen=signature(store.json,baseline(text(row.get("rowId"))).get("confirmationSnapshot"));
  withExclusiveSource(source,()->{RuntimeException conflict=assertThrows(RuntimeException.class,()->tx.execute(t->samples.create(single)));assertTrue(sqlState(conflict,"55P03"),conflict.toString());assertEquals(before,receiptWriteCounts());assertEquals(frozen,signature(store.json,baseline(text(row.get("rowId"))).get("confirmationSnapshot")));var http=new com.yuewei.plm.common.exception.GlobalExceptionHandler().handleReceiptSourceLock((org.springframework.dao.DataAccessException)conflict,new org.springframework.mock.web.MockHttpServletRequest("POST","/api/v1/samples"));assertEquals(409,http.getStatusCode().value());assertEquals(1,jdbc.queryForObject("select 1",Integer.class));});
  var second=tx.execute(t->samples.create(single));assertEquals(13L,number(second.get("phoneModelId")));changeSupply(source,values("phoneModelIds",List.of(12L),"modelText","Phone12"));var after=receiptWriteCounts();
  withExclusiveSource(source,()->{var replayBulk=tx.execute(t->samples.receiveSelection(id(),firstInput));assertEquals(number(maps(first.get("batches")).get(0).get("id")),number(maps(replayBulk.get("batches")).get(0).get("id")));assertEquals(second.get("id"),tx.execute(t->samples.create(single)).get("id"));var changedBulk=new LinkedHashMap<>(firstInput);changedBulk.put("date","2026-10-23");var bulkMismatch=assertThrows(RuntimeException.class,()->tx.execute(t->samples.receiveSelection(id(),changedBulk)));assertFalse(sqlState(bulkMismatch,"55P03"));assertTrue(bulkMismatch.getMessage().contains("内容不同"));var changedSingle=new LinkedHashMap<>(single);changedSingle.put("qty",3L);var singleMismatch=assertThrows(RuntimeException.class,()->tx.execute(t->samples.create(changedSingle)));assertFalse(sqlState(singleMismatch,"55P03"));assertTrue(singleMismatch.getMessage().contains("内容不同"));assertEquals(after,receiptWriteCounts());});assertEquals(frozen,signature(store.json,baseline(text(row.get("rowId"))).get("confirmationSnapshot")));System.out.println("SOURCE_LOCK_EVIDENCE replay kind="+kind+" bulkAndSingleReplayedUnderWriterLock=true sourceChanged=true historyUnchanged=true");
 }

